//! Checks the PHP that `PHP_CONFIG` (default `php-config`) describes (NTS or ZTS, non-debug)
//! and computes the module build id PHP checks at load time. The Zend bindings come from
//! ext-php-rs (generated by its build script, which also compiles its small wrapper.c: the only
//! C in the extension; no C libraries are linked). Set `PHP` to the matching php binary too:
//! ext-php-rs takes the PHP version from it. On Windows there is no php-config: everything comes
//! from `PHP` (php.exe; ext-php-rs downloads the matching development pack for the headers and
//! php8.lib), and the build needs a nightly Rust (ext-php-rs uses the unstable vectorcall ABI of
//! PHP's ZEND_FASTCALL functions there).

use std::process::Command;

fn run(cmd: &str, args: &[&str]) -> String {
    let out = Command::new(cmd).args(args).output().unwrap_or_else(|e| panic!("cannot run {cmd}: {e}"));
    assert!(out.status.success(), "{cmd} {args:?} failed");
    String::from_utf8(out.stdout).unwrap().trim().to_owned()
}

fn main() {
    println!("cargo:rerun-if-env-changed=PHP_CONFIG");
    println!("cargo:rerun-if-env-changed=PHP");
    // the layout checks in src/zend/layout.rs (and src/zend/sys.rs) are for 64-bit targets:
    // LP64 Unix and LLP64 Windows (the structs touched use no `long`)
    let width = std::env::var("CARGO_CFG_TARGET_POINTER_WIDTH").unwrap_or_default();
    let windows = std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows");
    if width != "64" || (std::env::var_os("CARGO_CFG_UNIX").is_none() && !windows) {
        panic!("only 64-bit Unix and Windows targets are supported (target pointer width {width})");
    }
    // graviola (the TLS crypto library) exists for these two architectures
    let arch = std::env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_default();
    if arch != "x86_64" && arch != "aarch64" {
        panic!("only x86_64 and aarch64 targets are supported (target architecture {arch})");
    }
    for v in ["php83", "php84", "php85", "php86"] {
        println!("cargo:rustc-check-cfg=cfg({v})");
    }
    println!("cargo:rustc-check-cfg=cfg(php_zts)");
    if windows {
        return windows_php();
    }
    let config = std::env::var("PHP_CONFIG").unwrap_or_else(|_| "php-config".into());
    let version = run(&config, &["--version"]);
    let php = std::env::var("PHP").unwrap_or_else(|_| run(&config, &["--php-binary"]));
    // `php-config --phpapi` is missing from some builds (Homebrew): ask the binary
    let api: u32 = run(&php, &["-n", "-i"])
        .lines()
        .find_map(|l| l.strip_prefix("PHP API => "))
        .and_then(|v| v.trim().parse().ok())
        .expect("PHP API number from php -i");
    // ext-php-rs takes the version from `PHP` and the headers from `PHP_CONFIG`: same minor version
    let php_version = run(&php, &["-n", "-r", "echo PHP_VERSION;"]);
    let minor = |v: &str| v.split('.').take(2).collect::<Vec<_>>().join(".");
    if minor(&php_version) != minor(&version) {
        panic!("PHP ({php}) is {php_version} but PHP_CONFIG ({config}) describes {version}: set both to the same PHP");
    }
    let zts = thread_safety(&php);
    // cumulative, as ext-php-rs's: `php85` means 8.5 or later
    let cfgs: &[&str] = match api {
        20220829 => &[],
        20230831 => &["php83"],
        20240924 => &["php83", "php84"],
        20250925 => &["php83", "php84", "php85"],
        // 8.6: 20260924 up to RC2, 20261112 since php-src 2c5097cb73
        20260924 | 20261112 => &["php83", "php84", "php85", "php86"],
        _ => panic!("unsupported PHP {version} (API {api}): supported are 8.2 to 8.6"),
    };
    // the Zend symbols are resolved from the php binary when the extension is loaded
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("macos") {
        println!("cargo:rustc-cdylib-link-arg=-undefined");
        println!("cargo:rustc-cdylib-link-arg=dynamic_lookup");
        // the system libraries Rust's std links (libiconv, ...) come from the SDK, even when
        // LIBRARY_PATH points at a package manager's copies (e.g. Homebrew's GNU libiconv)
        if let Ok(o) = Command::new("xcrun").arg("--show-sdk-path").output() {
            let sdk = String::from_utf8_lossy(&o.stdout).trim().to_owned();
            if o.status.success() && !sdk.is_empty() {
                println!("cargo:rustc-link-search=native={sdk}/usr/lib");
            }
        }
    }
    for cfg in cfgs {
        println!("cargo:rustc-cfg={cfg}");
    }
    if zts {
        // the engine's globals are per thread (TSRM); see src/zend/mod.rs
        println!("cargo:rustc-cfg=php_zts");
    }
    println!("cargo:rustc-env=PHP_MODULE_API={api}");
    println!("cargo:rustc-env=PHP_BUILD_ID=API{api},{}", if zts { "TS" } else { "NTS" });
}

/// Whether `php` is a thread-safe (ZTS) build; debug builds are refused.
fn thread_safety(php: &str) -> bool {
    let flags = run(php, &["-n", "-r", "echo (int) PHP_ZTS, (int) PHP_DEBUG;"]);
    match flags.as_str() {
        "00" => false,
        "10" => true,
        _ => panic!("only non-debug PHP builds are supported (PHP_ZTS/PHP_DEBUG = {flags})"),
    }
}

/// The cfg flags and module ids of the PHP that `PHP` (default `php`) runs, on Windows: there
/// the build id also names the compiler ("API20240924,NTS,VS17"; ZTS: "API20240924,TS,VS17"),
/// as `php -i` reports it.
fn windows_php() {
    let php = std::env::var("PHP").unwrap_or_else(|_| "php".into());
    let info = run(&php, &["-n", "-i"]);
    let key = |k: &str| info.lines().find_map(|l| l.strip_prefix(k)).map(|v| v.trim().to_owned());
    let api: u32 = key("PHP API => ").and_then(|v| v.parse().ok()).expect("PHP API number from php -i");
    let build_id = key("PHP Extension Build => ").expect("PHP Extension Build from php -i");
    let zts = thread_safety(&php);
    let cfgs: &[&str] = match api {
        20220829 => &[],
        20230831 => &["php83"],
        20240924 => &["php83", "php84"],
        20250925 => &["php83", "php84", "php85"],
        // 8.6: 20260924 up to RC2, 20261112 since php-src 2c5097cb73
        20260924 | 20261112 => &["php83", "php84", "php85", "php86"],
        _ => panic!("unsupported PHP (API {api}): supported are 8.2 to 8.6"),
    };
    if !build_id.starts_with(&format!("API{api},{},", if zts { "TS" } else { "NTS" })) {
        panic!("unexpected PHP extension build id {build_id}");
    }
    for cfg in cfgs {
        println!("cargo:rustc-cfg={cfg}");
    }
    if zts {
        println!("cargo:rustc-cfg=php_zts");
    }
    println!("cargo:rustc-env=PHP_MODULE_API={api}");
    println!("cargo:rustc-env=PHP_BUILD_ID={build_id}");
}
